    # Keep regularly spaced separator lines, including lines containing markers.
    def regular_positions(pos):
        if len(pos) < 2:
            return pos
        gaps = [b - a for a, b in zip(pos, pos[1:])]
        step = min(gaps)
        return [p for p in pos if (p - pos[0]) % step == 0]

    rs = regular_positions(line_rows)
    cs = regular_positions(line_cols)
    if len(rs) < 2 or len(cs) < 2:
        return grid

