def transform(grid):
    h, w = len(grid), len(grid[0])
    totals = [sum(row.count(c) for row in grid) for c in range(10)]
    line = max(range(10), key=lambda c: totals[c])

    # Locate the separator lattice.
    rows = [r for r in range(h) if sum(v == line for v in grid[r]) >= w - 2]
    cols = [c for c in range(w) if sum(grid[r][c] == line for r in range(h)) >= h - 2]

    # Read the colors at separator intersections, ignoring the regular line color.
    marks = {}
    for r in rows:
        for c in cols:
            v = grid[r][c]
            if v != line:
                marks[v] = marks.get(v, 0) + 1
    background = max((v for v in range(10) if v != line and v not in marks),
                     key=lambda v: totals[v], default=0)

    # The intersection lattice encodes the output as a 2x2 arrangement.
    # Each output cell takes the marker color occupying its corresponding
    # quadrant; otherwise it is the ordinary interior/background color.
    midr, midc = len(rows) // 2, len(cols) // 2
    result = []
    for rlo, rhi in ((0, midr), (midr, len(rows) - 1)):
        outrow = []
        for clo, chi in ((0, midc), (midc, len(cols) - 1)):
            freq = {}
            for i in range(rlo, rhi + 1):
                for j in range(clo, chi + 1):
                    v = grid[rows[i]][cols[j]]
                    if v != line:
                        freq[v] = freq.get(v, 0) + 1
            outrow.append(max(freq, key=freq.get) if freq else background)
        result.append(outrow)
    return result
